function asArray(item, key) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data[key])) return json.data[key];
  if (json && Array.isArray(json[key])) return json[key];
  return [];
}

const opportunities = asArray($('Fetch all Opportunities').item, 'opportunities');
const companies = asArray($('Fetch LiveClient Companies').item, 'companies');
const billingPeriods = asArray($('Fetch recent Billing Periods').item, 'billingPeriods');

const stageBreakdown = {};
for (const opp of opportunities) {
  const stage = opp.stage || 'Unknown';
  stageBreakdown[stage] = (stageBreakdown[stage] || 0) + 1;
}

const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
const revenueLast30dCents = billingPeriods
  .filter((bp) => bp.periodStart && new Date(bp.periodStart) >= thirtyDaysAgo)
  .reduce((sum, bp) => sum + (bp.revenueCents || 0), 0);

return [{
  json: {
    stageBreakdown,
    totalOpportunities: opportunities.length,
    activeClientCount: companies.length,
    revenueLast30dCents,
  },
}];

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { digest: textBlock.text } }];
